# Tests for the OSR v1 interchange consumer (`OpenSymbolicRules.OSRv1`).
#
# The fixture `test/data/osr1/trigonometry.osr.json` is generated by the
# Lean exporter of OpenSymbolicRules/Lean (`just export`).  Set
# `OSR1_RULESET` to test a freshly generated file instead.

@testitem "OSRv1: OpenMath JSON expressions" begin
    using OpenSymbolicRules.OSRv1
    using JSON

    x = OMV("x")
    e = OMA(OMS("transc1", "sin"), [x])
    j = JSON.parse(JSON.json(to_omjson(e)))
    @test j["kind"] == "OMA"
    @test j["applicant"] == Dict("kind" => "OMS", "cd" => "transc1", "name" => "sin")
    @test parse_omjson(j) == e
    @test parse_omjson(Dict("kind" => "OMI", "integer" => -2)) == OMI(-2)
    # Integers compare by value even though they are stored as BigInt.
    @test OMI(2) == OMI(big(2))
    @test hash(OMI(2)) == hash(OMI(2))
    @test_throws ArgumentError parse_omjson(Dict("kind" => "OMF", "float" => 1.0))
    @test_throws ArgumentError parse_omjson(Dict("kind" => "OMA",
        "applicant" => Dict("kind" => "OMV", "name" => "f"), "arguments" => [Dict("kind" => "OMV", "name" => "x")]))
end

@testitem "OSRv1: matching and substitution" begin
    using OpenSymbolicRules.OSRv1

    sin(e) = OMA(OMS("transc1", "sin"), [e])
    plus(a, b) = OMA(OMS("arith1", "plus"), [a, b])
    x, y, t = OMV("x"), OMV("y"), OMV("t")
    vars = Set(["x", "y"])

    b = match_pattern(sin(plus(x, y)), sin(plus(t, OMI(1))), vars)
    @test b == Dict("x" => t, "y" => OMI(1))
    @test match_pattern(sin(plus(x, x)), sin(plus(t, OMI(1))), vars) === nothing
    @test match_pattern(sin(plus(x, x)), sin(plus(t, t)), vars) == Dict("x" => t)
    # A non-variable OMV in the pattern only matches itself.
    @test match_pattern(sin(OMV("c")), sin(t), vars) === nothing
    @test substitute(plus(x, y), Dict("x" => t, "y" => OMI(2))) == plus(t, OMI(2))
end

@testitem "OSRv1: load the Lean-exported Trigonometry rule set" begin
    using OpenSymbolicRules.OSRv1

    path = get(ENV, "OSR1_RULESET", joinpath(@__DIR__, "data", "osr1", "trigonometry.osr.json"))
    rs = load_ruleset(path)
    @test rs.name == "trigonometry"
    @test length(rs.rules) == 13
    @test Set(keys(rs.profiles)) ==
        Set(["default", "product_to_sum", "power_reduction", "sum_to_product"])

    pyth = rs.rules["trigonometry.pythagorean"]
    @test pyth.legacy_id == "trigonometry:1-basic-identities/1.1-pythagorean:1"
    @test OMS("transc1", "sin") in pyth.symbols
    @test OMS("arith1", "power") in pyth.symbols
    v = verification(pyth, :real)
    @test v.status == "proved"
    @test v.certified
    @test v.theorem == "OSR.Trigonometry.pythagorean_real"
    @test issubset(v.axioms, ["propext", "Classical.choice", "Quot.sound"])
    @test pyth.provenance["sources"][1]["revision"] == "e9b6ef0e46495c9896b5dc168dabd5f7c1fa39b5"

    # Every proof listed as certified really has standard axioms only.
    for r in values(rs.rules), v in r.verification
        v.certified && @test v.status == "proved"
    end

    # Domain-specific certification is preserved, not merged.
    ta = rs.rules["trigonometry.inverse.tan_arctan"]
    @test verification(ta, :real).certified
    @test !verification(ta, :complex).certified
    @test verification(ta, :complex).mapping_assurance == "provisional"
    @test !isempty(ta.findings)

    # Profiles are oriented consistently: expansion and product-to-sum rules
    # are never enabled together (they cycle in the v0.1 `default` profile).
    @test "trigonometry.angle_sum.sin_add" in rs.profiles["default"]
    @test !("trigonometry.product_to_sum.sin_cos" in rs.profiles["default"])
    @test "trigonometry.product_to_sum.sin_cos" in rs.profiles["product_to_sum"]
    @test "trigonometry.sum_to_product.sin_add_sin" in rs.profiles["sum_to_product"]
    @test all(p -> "trigonometry.pythagorean" in p, values(rs.profiles))
end

@testitem "OSRv1: end-to-end rewrite with a Lean-certified rule" begin
    using OpenSymbolicRules.OSRv1

    path = get(ENV, "OSR1_RULESET", joinpath(@__DIR__, "data", "osr1", "trigonometry.osr.json"))
    rs = load_ruleset(path)

    sin(e) = OMA(OMS("transc1", "sin"), [e])
    cos(e) = OMA(OMS("transc1", "cos"), [e])
    sq(e) = OMA(OMS("arith1", "power"), [e, OMI(2)])
    plus(a, b) = OMA(OMS("arith1", "plus"), [a, b])
    t = OMV("t")

    # sin(t)^2 + cos(t)^2  ⟶  1, by trigonometry.pythagorean (proved over ℝ).
    result = rewrite(plus(sq(sin(t)), sq(cos(t))), rs; profile="default", domain=:real)
    @test result.expr == OMI(1)
    @test length(result.steps) == 1
    @test result.steps[1].rule == "trigonometry.pythagorean"
    @test result.steps[1].theorem == "OSR.Trigonometry.pythagorean_real"
    # Reaching a normal form on the last allowed step is not exhaustion.
    @test !rewrite(plus(sq(sin(t)), sq(cos(t))), rs; profile="default", domain=:real,
        max_steps=1).exhausted
    # sin((t + t) + t) needs two angle-sum steps.
    @test rewrite(sin(plus(plus(t, t), t)), rs; profile="default", domain=:real,
        max_steps=1).exhausted

    # Inside a larger expression, the rewrite applies to the subterm.  The
    # strategy is outermost-first, rules in profile order: no rule matches the
    # product at the root, so the engine descends into its operands.
    times(a, b) = OMA(OMS("arith1", "times"), [a, b])
    arg = plus(t, OMI(1))
    c = OMV("c")
    result = rewrite(times(c, plus(sq(sin(arg)), sq(cos(arg)))), rs; profile="default", domain=:real)
    @test result.expr == times(c, OMI(1))

    # tan(arctan t) ⟶ t is certified over ℝ but not over ℂ.
    ta = OMA(OMS("transc1", "tan"), [OMA(OMS("transc1", "arctan"), [t])])
    @test rewrite(ta, rs; profile="default", domain=:real).expr == t
    @test rewrite(ta, rs; profile="default", domain=:complex).expr == ta
    @test rewrite(ta, rs; profile="default", domain=:complex, certified_only=false).expr == t

    # sin(t + 1) expands once and stops: the v1 `default` profile no longer
    # contains product-to-sum, which reproduced sin(t + 1) in v0.1.
    expanded = rewrite(sin(plus(t, OMI(1))), rs; profile="default", domain=:real, max_steps=20)
    @test !expanded.exhausted
    @test [s.rule for s in expanded.steps] == ["trigonometry.angle_sum.sin_add"]

    # Unknown profiles are rejected.
    @test_throws ArgumentError rewrite(ta, rs; profile="nope", domain=:real)
end

@testitem "OSRv1: conformance with the Lean reference rewriter" begin
    using OpenSymbolicRules.OSRv1
    using JSON

    # Cases generated by OpenSymbolicRules/Lean (`just export`), from
    # `OSR.normalize`, whose soundness is proved in Lean.  Distributed by
    # OpenSymbolicRules/Conformance.
    # Every rule set is checked against its suite.  `OSR1_DIR` replaces the
    # fixtures with a fresh export directory (`just export` in the Lean repo).
    dir = get(ENV, "OSR1_DIR", joinpath(@__DIR__, "data", "osr1"))
    for name in ("trigonometry", "algebra", "logic")
        rspath = joinpath(dir, "$name.osr.json")
        suitepath = joinpath(dir, "conformance", "$name.cases.json")
        rs = load_ruleset(rspath)
        suite = JSON.parsefile(suitepath; dicttype=Dict{String,Any})
        @test suite["source_digest"] == rs.build["source_digest"]
        domain = Symbol(suite["semantics"]["domain"])
        fuel = suite["semantics"]["fuel"]
        @test length(suite["cases"]) > 0
        for c in suite["cases"]
            res = rewrite(parse_omjson(c["input"]), rs; profile=c["profile"], domain=domain,
                max_steps=fuel)
            @testset "$(suite["suite"]) $(c["id"])" begin
                @test res.expr == parse_omjson(c["expected"])
                @test [s.rule for s in res.steps] == String.(c["trace"])
                @test res.exhausted == !c["normal"]
            end
        end
    end
end
